import random, itertools, sys
from problems import NaeThreeSat, ThreeColoring
from reduce import reduce

def nae3sat_bruteforce(instance):
    m = instance['num_vars']
    clauses = instance['clauses']
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            vals = []
            for lit in clause:
                var = abs(lit)-1
                val = bits[var]
                if lit<0:
                    val = not val
                vals.append(val)
            if all(vals) or not any(vals):
                ok=False;break
        if ok:
            return True
    return False

def threecolor_bruteforce(instance):
    n=instance['n'];edges=instance['edges']
    for colors in itertools.product([0,1,2], repeat=n):
        good=True
        for u,v in edges:
            if colors[u]==colors[v]:
                good=False;break
        if good:
            return True
    return False

def random_nae_instance(max_vars=3, max_clauses=1):
    m=random.randint(0,max_vars)
    clauses=[]
    num_clauses=random.randint(0,max_clauses)
    for _ in range(num_clauses):
        if m<3: break
        vars=random.sample(range(1,m+1),3)
        clause=[]
        for v in vars:
            clause.append(v if random.choice([True,False]) else -v)
        clauses.append(clause)
    return {'num_vars':m,'clauses':clauses}

for i in range(30):
    inst=random_nae_instance()
    NaeThreeSat.validate(inst)
    red=reduce(inst)
    ThreeColoring.validate(red)
    a1=nae3sat_bruteforce(inst)
    a2=threecolor_bruteforce(red)
    if a1!=a2:
        print('FAIL',inst,red)
        sys.exit(0)
print('done')
